describe('Out of Stock Message', () => {
    beforeEach(() => {
        cy.visit('/products'); // Visit the products page
    });

    it('should display an out-of-stock message when adding an unavailable item to cart', () => {
        cy.get('.product-item').contains('Unavailable Item').click(); // Click on the unavailable item
        cy.get('.add-to-cart-button').click(); // Attempt to add to cart
        cy.get('.notification').should('be.visible'); // Check if notification is visible
        cy.get('.notification').should('contain', 'This item is currently out of stock'); // Verify the message
    });

    it('should not allow adding out-of-stock item to cart', () => {
        cy.get('.product-item').contains('Unavailable Item').click(); // Click on the unavailable item
        cy.get('.add-to-cart-button').should('be.disabled'); // Ensure the button is disabled
    });
});
